options.css:
@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700&family=Barlow:wght@400;500;600&family=Roboto+Mono:wght@500&display=swap');

:host, .board {
  --ink:#12161C; --panel:#1A2029; --rule:#2C3542; --rule-soft:#222A34;
  --text:#E6EAF0; --muted:#8A94A3;
  --ok:#4FA96A; --warn:#D9A128; --heat:#FF7A2F; --stop:#E14B4B; --idle:#4A5261;
  --cond:'Barlow Condensed','Roboto Condensed','Arial Narrow',system-ui,sans-serif;
  --body:'Barlow',system-ui,-apple-system,sans-serif;
  --mono:'Roboto Mono',ui-monospace,SFMono-Regular,Menlo,monospace;
}
* { box-sizing:border-box; margin:0; }
.board { background:var(--ink); color:var(--text); font-family:var(--body);
         padding:14px 16px 16px; height:100%; overflow:auto; }
.lines { display:grid; gap:14px; align-items:start; }

.line-head { border-top:2px solid var(--rule); padding:8px 0 10px; }
.line-name { font-family:var(--cond); font-weight:700; font-size:26px;
             letter-spacing:.06em; text-transform:uppercase; line-height:1; }
.line-verdict { font-family:var(--body); font-size:12.5px; font-weight:500;
                letter-spacing:.01em; margin-top:5px; color:var(--muted); }
.line-verdict.is-stop { color:var(--stop); }
.line-verdict.is-warn { color:var(--warn); }
.line-verdict.is-heat { color:var(--heat); }
.line-verdict.is-ok   { color:var(--ok); }

/* the chain: a station, then the link that carries the flow downstream */
.station { border:1px solid var(--rule-soft); border-left:3px solid var(--idle);
           background:var(--panel); padding:9px 11px 10px; }
.station.is-ok   { border-left-color:var(--ok); }
.station.is-warn { border-left-color:var(--warn); }
.station.is-heat { border-left-color:var(--heat); }
.station.is-stop { border-left-color:var(--stop); background:#241A1D; }
.st-top { display:flex; justify-content:space-between; align-items:baseline; gap:8px; }
.st-name { font-family:var(--cond); font-weight:600; font-size:14px; letter-spacing:.10em;
           text-transform:uppercase; color:var(--muted); }
.st-state { font-family:var(--cond); font-weight:700; font-size:30px; line-height:1.05;
            letter-spacing:.02em; margin:3px 0 1px; }
.station.is-ok   .st-state { color:var(--ok); }
.station.is-warn .st-state { color:var(--warn); }
.station.is-heat .st-state { color:var(--heat); }
.station.is-stop .st-state { color:var(--stop); }
.station.is-idle .st-state { color:var(--muted); }
.st-machine { font-size:11.5px; color:var(--muted); margin-bottom:7px;
              overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.st-metrics { display:flex; gap:14px; border-top:1px solid var(--rule-soft); padding-top:6px; }
.metric { display:flex; align-items:baseline; gap:5px; }
.metric-k { font-size:10px; color:var(--muted); letter-spacing:.06em; text-transform:uppercase; }
.metric-v { font-family:var(--mono); font-size:13px; font-weight:500; }
.metric-v.dim { color:var(--muted); }

/* flow link — solid steel when parts move on, torn when they do not */
.link { height:17px; position:relative; }
.link::before { content:''; position:absolute; left:0; top:-1px; bottom:-1px; width:3px;
                background:var(--ok); }
.link.is-broken::before { background:repeating-linear-gradient(
                to bottom, var(--stop) 0 3px, transparent 3px 7px); }
.link-note { position:absolute; left:11px; top:50%; transform:translateY(-50%);
             font-size:10px; letter-spacing:.06em; text-transform:uppercase;
             color:var(--stop); font-weight:600; white-space:nowrap; }

.empty { color:var(--muted); font-family:var(--body); font-size:13px; padding:20px 0; }

options.onRender:
var STATES = {
  0:['idle','idle'], 10:['running','ok'], 20:['setup','warn'], 30:['FAULT','stop'],
  40:['stopped','idle'], 50:['charging','ok'], 51:['heating','ok'], 52:['soaking','ok'],
  53:['quenching','ok'], 54:['discharging','ok'], 60:['filling','ok'], 61:['washing','ok'],
  62:['rinsing','ok'], 63:['drying','ok'], 64:['draining','ok'], 70:['tool change','heat']
};
var root = htmlNode.querySelector('.board');
if (!root) { return; }

function fields(series) {
  var f = {};
  (series.fields || []).forEach(function (fl) { f[fl.name] = fl.values.toArray ? fl.values.toArray() : fl.values; });
  return f;
}
var series = (data && data.series && data.series.length) ? data.series[0] : null;
if (!series) { root.innerHTML = '<div class="empty">No data for this time range.</div>'; return; }
var f = fields(series);
var n = (f.line || []).length;
if (!n) { root.innerHTML = '<div class="empty">No assets reported in this time range.</div>'; return; }

// group rows into lines, keeping process order
var lines = {}, order = [];
for (var i = 0; i < n; i++) {
  var ln = f.line[i];
  if (!lines[ln]) { lines[ln] = []; order.push(ln); }
  var code = f.state[i];
  var s = STATES[code] || [String(code), 'idle'];
  lines[ln].push({
    step: f.ord[i], station: f.station[i], machine: f.machine[i],
    label: s[0], tone: s[1], avail: f.availability[i], qual: f.quality[i]
  });
}
order.forEach(function (ln) { lines[ln].sort(function (a, b) { return a.step - b.step; }); });

function pct(v) { return (v === null || v === undefined) ? '—' : (v * 100).toFixed(0) + '%'; }
function esc(s) { return String(s === null || s === undefined ? '' : s).replace(/[&<>]/g, function (c) {
  return { '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]; }); }

var RANK = { stop: 3, warn: 2, heat: 2, idle: 1, ok: 0 };
var html = '<div class="lines" style="grid-template-columns:repeat(' + order.length + ',minmax(0,1fr))">';

order.forEach(function (ln) {
  var sts = lines[ln];
  // the verdict names where the chain breaks — that is the two-second answer
  var worst = sts.reduce(function (a, s) { return RANK[s.tone] > RANK[a.tone] ? s : a; }, sts[0]);
  var verdict, vtone = worst.tone;
  if (worst.tone === 'stop')      verdict = 'halted at ' + worst.station;
  else if (worst.tone === 'idle') verdict = worst.label + ' at ' + worst.station;
  else if (worst.tone === 'warn') verdict = worst.label + ' at ' + worst.station;
  else if (worst.tone === 'heat') verdict = worst.label + ' at ' + worst.station;
  else                            verdict = 'all three stations producing';

  html += '<div class="line"><div class="line-head">'
        + '<div class="line-name">' + esc(ln.replace('_', ' ')) + '</div>'
        + '<div class="line-verdict is-' + vtone + '">' + esc(verdict) + '</div></div>';

  sts.forEach(function (s, idx) {
    html += '<div class="station is-' + s.tone + '">'
          + '<div class="st-top"><span class="st-name">' + esc(s.station) + '</span></div>'
          + '<div class="st-state">' + esc(s.label) + '</div>'
          + '<div class="st-machine">' + esc(s.machine) + '</div>'
          + '<div class="st-metrics">'
          + '<span class="metric"><span class="metric-k">avail</span>'
          + '<span class="metric-v' + (s.avail === null ? ' dim' : '') + '">' + pct(s.avail) + '</span></span>'
          + '<span class="metric"><span class="metric-k">quality</span>'
          + '<span class="metric-v' + (s.qual === null ? ' dim' : '') + '">' + pct(s.qual) + '</span></span>'
          + '</div></div>';
    if (idx < sts.length - 1) {
      var flowing = s.tone === 'ok';
      html += '<div class="link' + (flowing ? '' : ' is-broken') + '">'
            + (flowing ? '' : '<span class="link-note">no flow</span>') + '</div>';
    }
  });
  html += '</div>';
});
html += '</div>';
root.innerHTML = html;
